package com.pirris.mapper;

import java.util.List;

import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.mapstruct.MappingConstants;

import com.pirris.dto.course.CourseDetailDto;
import com.pirris.dto.course.CourseParticipantDto;
import com.pirris.dto.course.CourseSummaryDto;
import com.pirris.model.CourseModel;
import com.pirris.model.CourseParticipantModel;

/**
 * Compile-time mapper from {@link CourseModel} / {@link CourseParticipantModel}
 * to the Corsi view DTOs. Generated by MapStruct as a CDI bean.
 */
@Mapper(componentModel = MappingConstants.ComponentModel.CDI)
public interface CourseMapper {

    // ---- entity -> DTO (reads) ----

    CourseSummaryDto toSummary(CourseModel course);

    List<CourseSummaryDto> toSummaries(List<CourseModel> courses);

    CourseParticipantDto toParticipantDto(CourseParticipantModel participant);

    List<CourseParticipantDto> toParticipantDtos(List<CourseParticipantModel> participants);

    /** A course template with its (already mapped) enrollments. */
    @Mapping(target = "id", source = "course.id")
    @Mapping(target = "name", source = "course.name")
    @Mapping(target = "weekday", source = "course.weekday")
    @Mapping(target = "startTime", source = "course.startTime")
    @Mapping(target = "durationMinutes", source = "course.durationMinutes")
    @Mapping(target = "maxCapacity", source = "course.maxCapacity")
    @Mapping(target = "location", source = "course.location")
    @Mapping(target = "serviceId", source = "course.serviceId")
    @Mapping(target = "active", source = "course.active")
    @Mapping(target = "notes", source = "course.notes")
    @Mapping(target = "participants", source = "participants")
    CourseDetailDto toDetail(CourseModel course, List<CourseParticipantDto> participants);
}
